import{_ as a,a as o,b as t,c as n,d as i,e as r,f as s}from"./chunks/profile-change-detection.DQYOLpHf.js";import{_ as l,o as p,c,aj as h}from"./chunks/framework.C6uXqnaX.js";const w=JSON.parse('{"title":"Profiling with the Chrome DevTools","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"best-practices/profiling-with-chrome-devtools.md","filePath":"best-practices/profiling-with-chrome-devtools.md"}'),d={name:"best-practices/profiling-with-chrome-devtools.md"};function g(m,e,u,f,k,b){return p(),c("div",null,e[0]||(e[0]=[h('<h1 id="profiling-with-the-chrome-devtools" tabindex="-1">Profiling with the Chrome DevTools <a class="header-anchor" href="#profiling-with-the-chrome-devtools" aria-label="Permalink to &quot;Profiling with the Chrome DevTools&quot;">​</a></h1><p>Angular integrates with the <a href="https://developer.chrome.com/docs/devtools/performance/extension" target="_blank" rel="noreferrer">Chrome DevTools extensibility API</a> to present framework-specific data and insights directly in the <a href="https://developer.chrome.com/docs/devtools/performance/overview" target="_blank" rel="noreferrer">Chrome DevTools performance panel</a>.</p><p>With the integration enabled, you can <a href="https://developer.chrome.com/docs/devtools/performance#record" target="_blank" rel="noreferrer">record a performance profile</a> containing two sets of data:</p><ul><li>Standard performance entries based on Chrome&#39;s understanding of your code executing in a browser, and</li><li>Angular-specific entries contributed by the framework&#39;s runtime.</li></ul><p>Both sets of data are presented together on the same tab, but on separate tracks:</p><img alt="Angular custom track in Chrome DevTools profiler" src="'+a+`"><p>Angular-specific data are expressed in terms of framework concepts (components, change detection, lifecycle hooks, etc.) alongside lower-level function and method calls captured by a browser. These two data sets are correlated, and you can switch between the different views and level of details.</p><p>You can use the Angular track to better understand how your code runs in the browser, including:</p><ul><li>Determining whether a given code block is part of the Angular application, or whether it belongs to another script running on the same page.</li><li>Identifying performance bottlenecks and attribute those to specific components or services.</li><li>Gaining deeper insight into Angular&#39;s inner working with a visual breakdown of each change detection cycle.</li></ul><h2 id="recording-a-profile" tabindex="-1">Recording a profile <a class="header-anchor" href="#recording-a-profile" aria-label="Permalink to &quot;Recording a profile&quot;">​</a></h2><h3 id="enable-integration" tabindex="-1">Enable integration <a class="header-anchor" href="#enable-integration" aria-label="Permalink to &quot;Enable integration&quot;">​</a></h3><p>You can enable Angular profiling in one of two ways:</p><ol><li>Run <a href="https://angular.dev/api/core/enableProfiling" target="_blank" rel="noreferrer"><code>ng.enableProfiling()</code></a> in Chrome&#39;s console panel, or</li><li>Include a call to <a href="https://angular.dev/api/core/enableProfiling" target="_blank" rel="noreferrer"><code>enableProfiling()</code></a> in your application startup code (imported from <code>@angular/core</code>).</li></ol><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Angular profiling works exclusively in development mode.</p></div><p>Here is an example of how you can enable the integration in the application bootstrap to capture all possible events:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {enableProfiling} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@angular/core&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {bootstrapApplication} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@angular/platform-browser&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {MyApp} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;./my-app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Turn on profiling *before* bootstrapping your application</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in order to capture all of the code run on start-up.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enableProfiling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bootstrapApplication</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(MyApp);</span></span></code></pre></div><h3 id="record-a-profile" tabindex="-1">Record a profile <a class="header-anchor" href="#record-a-profile" aria-label="Permalink to &quot;Record a profile&quot;">​</a></h3><p>Use the <strong>Record</strong> button in the Chrome DevTools performance panel:</p><img alt="Recording a profile" src="`+o+'"><p>See the <a href="https://developer.chrome.com/docs/devtools/performance#record" target="_blank" rel="noreferrer">Chrome DevTools documentation</a> for more details on recording profiles.</p><h2 id="open-a-component-in-angular-devtools" tabindex="-1">Open a component in Angular DevTools <a class="header-anchor" href="#open-a-component-in-angular-devtools" aria-label="Permalink to &quot;Open a component in Angular DevTools&quot;">​</a></h2><p>After recording a profile, select a component event in the <strong>Angular</strong> track. The <strong>Summary</strong> tab can include a <strong>Component</strong> link that uses the <code>angular-devtools://component/...</code> URL scheme.</p><img alt="Chrome DevTools Performance panel showing an Angular custom track with a selected _MainComponent event. The Summary tab displays a Component link that uses the angular-devtools://component URL scheme." src="'+t+'"><p>Click the link to open Angular DevTools and select the matching component in the <strong>Components</strong> tab. This helps you move from a browser-level profile to the component state and metadata for a selected event.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Opening component links requires Angular DevTools for Chrome and Chrome&#39;s experimental <code>chrome://flags/#enable-devtools-deep-link-via-extensibility-api</code> flag.</p></div><h2 id="interpreting-a-recorded-profile" tabindex="-1">Interpreting a recorded profile <a class="header-anchor" href="#interpreting-a-recorded-profile" aria-label="Permalink to &quot;Interpreting a recorded profile&quot;">​</a></h2><p>You can use the &quot;Angular&quot; custom track to quickly identify and diagnose performance issues. The following sections describe some common profiling scenarios.</p><h3 id="differentiating-between-your-angular-application-and-other-tasks-on-the-same-page" tabindex="-1">Differentiating between your Angular application and other tasks on the same page <a class="header-anchor" href="#differentiating-between-your-angular-application-and-other-tasks-on-the-same-page" aria-label="Permalink to &quot;Differentiating between your Angular application and other tasks on the same page&quot;">​</a></h3><p>As Angular and Chrome data are presented on the separate but correlated tracks, you can see when Angular&#39;s application code is executed as opposed to some other browser processing (typically layout and paint) or other scripts running on the same page (in this case the custom Angular track does not have any data):</p><img alt="Profile data: Angular vs. 3rd party scripts execution" src="'+n+'"><p>This allows you to determine whether further investigations should focus on the Angular application code or on other parts of your codebase or dependencies.</p><h3 id="color-coding" tabindex="-1">Color-coding <a class="header-anchor" href="#color-coding" aria-label="Permalink to &quot;Color-coding&quot;">​</a></h3><p>Angular uses colors in the flame chart graph to distinguish tasks types:</p><ul><li>🟦 Blue represents TypeScript code written by the application developer (for example: services, component constructors and lifecycle hooks, etc.).</li><li>🟪 Purple represents templates code written by the application developer and transformed by the Angular compiler.</li><li>🟩 Green represents entry points to the application code and identifies <em>reasons</em> for executing code.</li></ul><p>The following examples illustrate the described color-coding in various, real-life recordings.</p><h4 id="example-application-bootstrapping" tabindex="-1">Example: Application bootstrapping <a class="header-anchor" href="#example-application-bootstrapping" aria-label="Permalink to &quot;Example: Application bootstrapping&quot;">​</a></h4><p>The application bootstrap process usually consists of:</p><ul><li>Triggers marked in blue, such as the call to the <code>bootstrapApplication</code>, instantiation of the root component, and initial change detection</li><li>Various DI services instantiated during bootstrap, marked in green.</li></ul><img alt="Profile data: bootstrap application" src="'+i+'"><h4 id="example-component-execution" tabindex="-1">Example: Component execution <a class="header-anchor" href="#example-component-execution" aria-label="Permalink to &quot;Example: Component execution&quot;">​</a></h4><p>One component processing is typically represented as an entry point (blue) followed by its template execution (purple). A template might, in turn, trigger instantiation of directives and execution of lifecycle hooks (green):</p><img alt="Profile data: component processing" src="'+r+'"><h4 id="example-change-detection" tabindex="-1">Example: Change detection <a class="header-anchor" href="#example-change-detection" aria-label="Permalink to &quot;Example: Change detection&quot;">​</a></h4><p>A change detection cycle usually consists of one or more data synchronization passes (blue), where each pass traverses a subset of components.</p><img alt="Profile data: change detection" src="'+s+'"><p>With this data visualization, it is possible to immediately identify components that were involved in the change detection and which were skipped (typically the <code>OnPush</code> components that were not marked dirty).</p><p>Additionally, you can inspect the number of synchronization passes for one change detection. Having more than one synchronization pass suggest that state is updated during change detection. You should avoid this, as it slows down page updates and can even result in infinite loops in the worst cases.</p>',47)]))}const A=l(d,[["render",g]]);export{w as __pageData,A as default};
